
import { NextResponse } from 'next/server';
import { createClient } from '@supabase/supabase-js';

// Initialize Supabase client with ANON key to simulate client-side/public access
const supabaseUrl = process.env.NEXT_PUBLIC_SUPABASE_URL!;
const supabaseAnonKey = process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!;

// Note: In a real client-side request, the user's session token would be passed.
// Here we are testing if the table is publicly readable (common for non-user-specific data like this).
const supabase = createClient(supabaseUrl, supabaseAnonKey);

export async function GET() {
    try {
        const videoId = 'Ed_wCBVhGfE';
        console.log(`Testing Anon Access for ${videoId}...`);

        const { data, error } = await supabase
            .from('nde_analysis')
            .select('*')
            .eq('video_id', videoId)
            .single();

        if (error) {
            console.error('Anon Access Error:', error);
            return NextResponse.json({ status: 'error', error: error.message, details: error }, { status: 403 });
        }

        return NextResponse.json({ status: 'success', data });

    } catch (err: any) {
        return NextResponse.json({ error: err.message }, { status: 500 });
    }
}
